// รับ JSON สุดท้ายจาก Agent 3 (Art Director QA) แล้วแตกเป็นรายการภาพ: ปก 1 + หน้าระบายสี
let raw = $input.first().json.choices[0].message.content;
let s = String(raw).trim().replace(/^\`\`\`(?:json)?\s*/i, '').replace(/\`\`\`\s*$/, '');
const a = s.indexOf('{'); const b = s.lastIndexOf('}');
if (a >= 0 && b > a) s = s.slice(a, b + 1);
const out = JSON.parse(s);

const stamp = $now.toFormat('yyyyLLdd_HHmm');
const slug = (out.theme_slug || out.theme || 'Theme').replace(/[^A-Za-z0-9]+/g, '');
const safeTitle = (out.book_title || 'Coloring Book').replace(/[^A-Za-z0-9 '\-]+/g, '').trim();
const meta = {
  theme: out.theme,
  theme_slug: slug,
  book_title: out.book_title,
  main_character: out.main_character || '',
  description: out.description || '',
  keywords: Array.isArray(out.keywords) ? out.keywords : [],
  folder_name: 'ColoringBook_' + slug + '_' + stamp,
  pdf_name: safeTitle + '.pdf',
};

const items = [{ json: { ...meta, index: 0, kind: 'cover', filename: 'cover.jpg', prompt: out.cover_prompt } }];
(out.page_prompts || []).forEach((p, i) => {
  items.push({ json: { ...meta, index: i + 1, kind: 'page', filename: 'page_' + (i + 1) + '.jpg', prompt: p } });
});
return items;

// แปลง base64 จาก gpt-image-1 เป็นไฟล์ binary — ถ้าภาพล้มเหลว เก็บ error ไว้รายงานในอีเมล (ไม่หยุดทั้งชุด)
const meta = $('Loop Over Images').first().json;
const resp = $input.first().json;
const b64 = resp && resp.data && resp.data[0] && resp.data[0].b64_json;
if (!b64) {
  const err = (resp && resp.error && (resp.error.message || resp.error.description || resp.error.code)) ||
    (resp && resp.message) || JSON.stringify(resp || {}).slice(0, 300);
  return [{ json: { ...meta, failed: true, error_message: String(err) } }];
}
const binary = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), meta.filename, 'image/jpeg');
return [{ json: { ...meta, failed: false }, binary: { data: binary } }];

// รวมเล่ม PDF (A4 แนวนอน, JavaScript ล้วน) + เตรียมไฟล์แนบและข้อความอีเมลแบบ KIT
function jpegInfo(buf) {
  let i = 2;
  while (i < buf.length - 8) {
    if (buf[i] !== 0xff) { i++; continue; }
    const marker = buf[i + 1];
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      return { height: buf.readUInt16BE(i + 5), width: buf.readUInt16BE(i + 7), components: buf[i + 9] };
    }
    const len = buf.readUInt16BE(i + 2);
    i += 2 + len;
  }
  return { width: 1536, height: 1024, components: 3 };
}

function buildPdf(images) {
  const W = 841.89, H = 595.28, M = 18; // A4 landscape (points) + ขอบขาวรอบภาพ
  const nObjs = 2 + images.length * 3;
  const chunks = [];
  let offset = 0;
  const offsets = new Array(nObjs + 1).fill(0);
  const push = (strOrBuf) => {
    const b = Buffer.isBuffer(strOrBuf) ? strOrBuf : Buffer.from(strOrBuf, 'latin1');
    chunks.push(b);
    offset += b.length;
  };
  const beginObj = (n) => { offsets[n] = offset; push(n + ' 0 obj\n'); };

  push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  const pageObjNums = images.map((_, k) => 5 + k * 3);
  beginObj(1);
  push('<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');
  beginObj(2);
  push('<< /Type /Pages /Kids [' + pageObjNums.map((n) => n + ' 0 R').join(' ') + '] /Count ' + images.length + ' >>\nendobj\n');

  images.forEach((img, k) => {
    const info = jpegInfo(img.buf);
    const cs = info.components === 1 ? '/DeviceGray' : '/DeviceRGB';
    const maxW = W - 2 * M, maxH = H - 2 * M;
    const scale = Math.min(maxW / info.width, maxH / info.height);
    const dw = info.width * scale, dh = info.height * scale;
    const x = (W - dw) / 2, y = (H - dh) / 2;
    const imgObj = 3 + k * 3, contObj = 4 + k * 3, pageObj = 5 + k * 3;

    beginObj(imgObj);
    push('<< /Type /XObject /Subtype /Image /Width ' + info.width + ' /Height ' + info.height +
      ' /ColorSpace ' + cs + ' /BitsPerComponent 8 /Filter /DCTDecode /Length ' + img.buf.length + ' >>\nstream\n');
    push(img.buf);
    push('\nendstream\nendobj\n');

    const content = 'q ' + dw.toFixed(2) + ' 0 0 ' + dh.toFixed(2) + ' ' + x.toFixed(2) + ' ' + y.toFixed(2) + ' cm /Im0 Do Q';
    beginObj(contObj);
    push('<< /Length ' + content.length + ' >>\nstream\n' + content + '\nendstream\nendobj\n');

    beginObj(pageObj);
    push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + W + ' ' + H + '] /Resources << /XObject << /Im0 ' +
      imgObj + ' 0 R >> >> /Contents ' + contObj + ' 0 R >>\nendobj\n');
  });

  const xrefStart = offset;
  push('xref\n0 ' + (nObjs + 1) + '\n0000000000 65535 f \n');
  for (let n = 1; n <= nObjs; n++) push(String(offsets[n]).padStart(10, '0') + ' 00000 n \n');
  push('trailer\n<< /Size ' + (nObjs + 1) + ' /Root 1 0 R >>\nstartxref\n' + xrefStart + '\n%%EOF\n');
  return Buffer.concat(chunks);
}

const onePx = '/9j/4AAQSkZJRgABAQEAYABgAAD/2wBDAP//////////////////////////////////////////////////////////////////////////////////////wgALCAABAAEBAREA/8QAFBABAAAAAAAAAAAAAAAAAAAAAP/aAAgBAQABPxA=';

const entries = $input.all().map((item, idx) => ({ item, idx }));
entries.sort((a, b) => a.item.json.index - b.item.json.index);
const meta = entries[0].item.json;

const good = [];
const failed = [];
for (const e of entries) {
  if (e.item.json.failed || !e.item.binary || !e.item.binary.data) { failed.push(e.item.json); continue; }
  let buf;
  try { buf = await this.helpers.getBinaryDataBuffer(e.idx, 'data'); }
  catch (err) { buf = Buffer.from(e.item.binary.data.data, 'base64'); }
  good.push({ buf, json: e.item.json });
}
if (good.length === 0) {
  throw new Error('ไม่มีภาพที่สร้างสำเร็จเลยสักภาพ — สาเหตุแรก: ' + ((failed[0] && failed[0].error_message) || 'unknown'));
}

const pdfBuf = buildPdf(good.map(g => ({ buf: g.buf })));
const binary = {};
binary.data = await this.helpers.prepareBinaryData(pdfBuf, meta.pdf_name, 'application/pdf');
const coverEntry = good.find(g => g.json.kind === 'cover');
binary.cover = await this.helpers.prepareBinaryData(coverEntry ? coverEntry.buf : Buffer.from(onePx, 'base64'), 'cover.jpg', 'image/jpeg');

let warnBlock = '';
if (failed.length) {
  warnBlock = '\n⚠️ ภาพเจนไม่สำเร็จ ' + failed.length + ' รูป: ' + failed.map(f => f.filename).join(', ');
  const fe = failed[0].error_message || '';
  if (fe) {
    warnBlock += '\nสาเหตุจาก OpenAI: ' + fe;
    if (/quota|billing|insufficient/i.test(fe)) warnBlock += '\n→ เครดิต OpenAI หมด! เติมเงินที่ platform.openai.com → Billing แล้วรันใหม่';
    if (/must be verified|verification/i.test(fe)) warnBlock += '\n→ บัญชี OpenAI ยังไม่ Verify Organization — ไปที่ platform.openai.com → Settings → Organization → Verify';
  }
  warnBlock += '\n→ PDF ชุดนี้มีเฉพาะหน้าที่สำเร็จ (' + good.length + ' หน้า) ควรรันใหม่ก่อนนำไปขาย\n';
}

const pageCount = good.filter(g => g.json.kind === 'page').length;
const kit = [
  '====== 🎨 COLORING BOOK UPLOAD KIT (คัดลอกวางตอนลงขายได้เลย) ======',
  warnBlock,
  '',
  '[TITLE]',
  meta.book_title,
  '',
  '[DESCRIPTION]',
  meta.description || '-',
  '',
  '[ART THEME]  ' + meta.theme,
  '[MAIN CHARACTER]  ' + (meta.main_character || '-'),
  '[PAGES]  ปกสี 1 หน้า + หน้าระบายสีขาวดำ ' + pageCount + ' หน้า (A4 แนวนอน มีกรอบเว้นขอบกระดาษ)',
  '[PRICE]  $3.50 (ช่วงแนะนำ $2.50 - $5.00)',
  '[SEARCH KEYWORDS]  ' + ((meta.keywords || []).join(', ') || '-'),
  '',
  '[FILE]  แนบไฟล์ PDF รวมเล่มในอีเมลนี้: ' + meta.pdf_name,
  '[PREVIEW/COVER]  ใช้ไฟล์ cover.jpg ในอีเมลนี้เป็นภาพปก/ภาพพรีวิวตอนลงขาย',
  '',
  'เหมาะสำหรับ: เด็กเล็ก - ประถม และสายระบายสีทุกวัย (Etsy / TPT / Amazon KDP)',
  '===============================================',
].join('\n');

return [{
  json: {
    book_title: meta.book_title,
    theme: meta.theme,
    main_character: meta.main_character || '',
    description: meta.description || '',
    keywords: meta.keywords || [],
    pdf_name: meta.pdf_name,
    total_pages: good.length,
    coloring_pages: pageCount,
    has_failures: failed.length > 0,
    kit: kit,
  },
  binary,
}];

// ลงขายบน Etsy อัตโนมัติ (Etsy Open API v3)
// ขั้นตอน: ต่ออายุ access token -> สร้าง draft listing -> อัปโหลดภาพปก -> อัปโหลดไฟล์ PDF -> (ถ้าเปิดไว้) publish
// โหนดนี้ส่งไฟล์แนบ (binary) ต่อไปให้ Gmail เหมือนเดิม ไม่ว่าจะสำเร็จหรือไม่

const cfg = $('Config').first().json;
const item = $input.first();
const info = item.json;

const API = 'https://openapi.etsy.com/v3/application';
const TOKEN_URLS = ['https://openapi.etsy.com/v3/public/oauth/token', 'https://api.etsy.com/v3/public/oauth/token'];

const out = (extra) => [{ json: { ...info, ...extra }, binary: item.binary }];
const block = (lines) => '\n\n====== 🛒 ETSY ======\n' + lines.join('\n') + '\n====================';

const keystring = String(cfg.etsy_keystring || '').trim();
const shopId = String(cfg.etsy_shop_id || '').trim();
const taxonomyId = Number(cfg.etsy_taxonomy_id || 0);
const price = Number(cfg.etsy_price || 0);
const quantity = Number(cfg.etsy_quantity || 999);
const doPublish = cfg.etsy_publish === true || String(cfg.etsy_publish) === 'true';

// refresh token: ใช้ตัวล่าสุดที่ Etsy คืนมา (เก็บใน workflow static data) ถ้ายังไม่มีค่อยใช้จาก Config
const store = $getWorkflowStaticData('global');
let refreshToken = String(store.etsy_refresh_token || cfg.etsy_refresh_token || '').trim();

// ---- ตรวจว่าตั้งค่าครบหรือยัง (ยังไม่ครบก็ไม่ error แค่บอกในอีเมล) ----
const unset = v => !v || /^(YOUR_|PUT_|<)/i.test(String(v));
const missing = [];
if (unset(keystring)) missing.push('etsy_keystring (API keystring จาก Etsy app)');
if (unset(refreshToken)) missing.push('etsy_refresh_token (ได้จากสคริปต์ขอสิทธิ์ครั้งแรก)');
if (unset(shopId)) missing.push('etsy_shop_id (เลข shop id ของร้าน)');
if (!taxonomyId) missing.push('etsy_taxonomy_id (หมวดหมู่สินค้า)');
if (!price) missing.push('etsy_price (ราคาขาย)');
if (missing.length) {
  return out({
    etsy_status: 'not_configured',
    etsy_block: block(['⚠️ ยังไม่ได้ลงขาย เพราะยังตั้งค่าไม่ครบในโหนด Config:', ...missing.map(m => '  - ' + m), 'ดูวิธีขอค่าเหล่านี้ในคู่มือ: คู่มือลงขาย_Etsy.md']),
  });
}

// ---- helper: multipart/form-data ประกอบเองเป็น Buffer (แน่นอนกว่าให้ library เดา) ----
function multipart(fields) {
  const boundary = '----n8nEtsyBoundary' + Date.now().toString(16) + Math.random().toString(16).slice(2, 8);
  const parts = [];
  for (const f of fields) {
    let head = '--' + boundary + '\r\nContent-Disposition: form-data; name="' + f.name + '"';
    if (f.filename) head += '; filename="' + f.filename + '"';
    head += '\r\n';
    if (f.contentType) head += 'Content-Type: ' + f.contentType + '\r\n';
    head += '\r\n';
    parts.push(Buffer.from(head, 'utf8'));
    parts.push(Buffer.isBuffer(f.buffer) ? f.buffer : Buffer.from(String(f.value == null ? '' : f.value), 'utf8'));
    parts.push(Buffer.from('\r\n', 'utf8'));
  }
  parts.push(Buffer.from('--' + boundary + '--\r\n', 'utf8'));
  return { body: Buffer.concat(parts), contentType: 'multipart/form-data; boundary=' + boundary };
}
const parseBody = r => { if (r && typeof r === 'object') return r; try { return JSON.parse(String(r)); } catch (e) { return {}; } };
const errText = e => {
  const b = (e && e.response && (e.response.body || e.response.data)) || e.cause || '';
  const s = typeof b === 'string' ? b : JSON.stringify(b || {});
  return (String(e && e.message || e) + ' ' + s).slice(0, 300);
};

// ---- เตรียมข้อมูล listing ให้ตรงกฎ Etsy ----
// title: ไม่เกิน 140 ตัวอักษร และต้องขึ้นต้นด้วยตัวอักษร/ตัวเลข
let title = (info.book_title || 'Coloring Book') + ' | Printable Coloring Book, ' +
  (info.coloring_pages || 5) + ' Pages, Kids Coloring Pages, Instant Download';
title = title.replace(/[^A-Za-z0-9 ,.|'&-]/g, '').replace(/^[^A-Za-z0-9]+/, '').replace(/\s+/g, ' ').trim().slice(0, 140).trim();

// tags: สูงสุด 13 อัน อันละไม่เกิน 20 ตัวอักษร ใช้ได้เฉพาะตัวอักษร ตัวเลข - _ ' และเว้นวรรค ห้ามซ้ำ
const seen = new Set();
const tags = [];
for (const raw of [].concat(info.keywords || [], ['coloring book', 'coloring pages', 'printable', 'instant download', 'kids activity'])) {
  const t = String(raw).replace(/[^A-Za-z0-9 '_-]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 20).trim();
  const k = t.toLowerCase();
  if (t && !seen.has(k)) { seen.add(k); tags.push(t); }
  if (tags.length >= 13) break;
}

const description = [
  info.description || '',
  '',
  '★ WHAT YOU GET',
  '- 1 PDF file, ' + (info.total_pages || 6) + ' pages (A4 landscape, print-ready)',
  '- 1 full-color cover page',
  '- ' + (info.coloring_pages || 5) + ' black-and-white coloring pages with bold, easy-to-color lines',
  '',
  '★ INSTANT DOWNLOAD',
  'This is a digital product. No physical item will be shipped. Download the file right after purchase and print it as many times as you like for personal use.',
  '',
  '★ HOW TO USE',
  'Print on A4 or Letter paper (landscape). Works with crayons, colored pencils and markers.',
  '',
  'Theme: ' + (info.theme || '') + (info.main_character ? ' | Character: ' + info.main_character : ''),
  '',
  'For personal use only. Please do not resell or redistribute the files.',
].join('\n');

const notes = [];
try {
  // ---- 1) ต่ออายุ access token (refresh token มีอายุ 90 วัน / access token 1 ชม.) ----
  let tok = null, tokErr = '';
  for (const url of TOKEN_URLS) {
    try {
      tok = parseBody(await this.helpers.httpRequest({
        method: 'POST', url,
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: 'grant_type=refresh_token&client_id=' + encodeURIComponent(keystring) + '&refresh_token=' + encodeURIComponent(refreshToken),
        json: false, timeout: 30000,
      }));
      if (tok && tok.access_token) break;
    } catch (e) { tokErr = errText(e); tok = null; }
  }
  if (!tok || !tok.access_token) throw new Error('ขอ access token ไม่สำเร็จ: ' + (tokErr || 'ไม่มี access_token ในคำตอบ'));
  const accessToken = tok.access_token;
  if (tok.refresh_token) store.etsy_refresh_token = tok.refresh_token; // Etsy หมุน refresh token ทุกครั้ง เก็บตัวใหม่ไว้ใช้รอบหน้า

  const auth = { 'x-api-key': keystring, 'Authorization': 'Bearer ' + accessToken };

  // ---- 2) สร้าง draft listing ----
  const payload = {
    quantity: quantity,
    title: title,
    description: description,
    price: price,
    who_made: 'i_did',
    when_made: 'made_to_order',
    taxonomy_id: taxonomyId,
    type: 'download',
    is_supply: false,
    tags: tags,
  };
  if (cfg.etsy_shipping_profile_id) payload.shipping_profile_id = Number(cfg.etsy_shipping_profile_id);

  let listing = null, createErr = '';
  try {
    listing = parseBody(await this.helpers.httpRequest({
      method: 'POST', url: API + '/shops/' + shopId + '/listings',
      headers: { ...auth, 'Content-Type': 'application/json' },
      body: payload, json: true, timeout: 60000,
    }));
  } catch (e) {
    createErr = errText(e);
    // สำรอง: บางบัญชี Etsy รับเฉพาะ x-www-form-urlencoded (tags ส่งเป็น comma-separated)
    const form = Object.entries({ ...payload, tags: tags.join(',') })
      .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
      .join('&');
    listing = parseBody(await this.helpers.httpRequest({
      method: 'POST', url: API + '/shops/' + shopId + '/listings',
      headers: { ...auth, 'Content-Type': 'application/x-www-form-urlencoded' },
      body: form, json: false, timeout: 60000,
    }));
    if (listing && listing.listing_id) notes.push('หมายเหตุ: ส่งแบบ JSON ไม่ผ่าน ใช้แบบ form แทน (' + createErr.slice(0, 80) + ')');
  }
  const listingId = listing && (listing.listing_id || (listing.results && listing.results[0] && listing.results[0].listing_id));
  if (!listingId) throw new Error('สร้าง listing ไม่สำเร็จ: ' + (createErr || JSON.stringify(listing).slice(0, 250)));

  // ---- 3) อัปโหลดภาพปกเป็นรูปสินค้า ----
  try {
    const cover = await this.helpers.getBinaryDataBuffer(0, 'cover');
    const mp = multipart([
      { name: 'image', filename: 'cover.jpg', contentType: 'image/jpeg', buffer: cover },
      { name: 'rank', value: '1' },
    ]);
    await this.helpers.httpRequest({
      method: 'POST', url: API + '/shops/' + shopId + '/listings/' + listingId + '/images',
      headers: { ...auth, 'Content-Type': mp.contentType }, body: mp.body, json: false, timeout: 120000,
    });
  } catch (e) { notes.push('⚠️ อัปโหลดภาพปกไม่สำเร็จ: ' + errText(e).slice(0, 120)); }

  // ---- 4) อัปโหลดไฟล์ PDF ที่ลูกค้าจะได้รับ ----
  try {
    const pdf = await this.helpers.getBinaryDataBuffer(0, 'data');
    const mp = multipart([
      { name: 'file', filename: info.pdf_name || 'coloring_book.pdf', contentType: 'application/pdf', buffer: pdf },
      { name: 'name', value: info.pdf_name || 'coloring_book.pdf' },
      { name: 'rank', value: '1' },
    ]);
    await this.helpers.httpRequest({
      method: 'POST', url: API + '/shops/' + shopId + '/listings/' + listingId + '/files',
      headers: { ...auth, 'Content-Type': mp.contentType }, body: mp.body, json: false, timeout: 180000,
    });
  } catch (e) { notes.push('⚠️ อัปโหลดไฟล์ PDF ไม่สำเร็จ: ' + errText(e).slice(0, 120)); }

  // ---- 5) เปิดขายจริง (ถ้าเปิดสวิตช์ไว้ — Etsy คิดค่าลงสินค้า $0.20 ตอนนี้) ----
  let state = 'draft';
  if (doPublish) {
    try {
      await this.helpers.httpRequest({
        method: 'PATCH', url: API + '/shops/' + shopId + '/listings/' + listingId,
        headers: { ...auth, 'Content-Type': 'application/json' },
        body: { state: 'active' }, json: true, timeout: 60000,
      });
      state = 'active';
    } catch (e) { notes.push('⚠️ เปิดขายอัตโนมัติไม่สำเร็จ (ยังเป็น draft อยู่): ' + errText(e).slice(0, 120)); }
  }

  const editUrl = 'https://www.etsy.com/your/shops/me/tools/listings/' + listingId;
  return out({
    etsy_status: state,
    etsy_listing_id: listingId,
    etsy_url: editUrl,
    etsy_block: block([
      (state === 'active' ? '✅ ลงขายแล้ว (เปิดขายจริง)' : '✅ สร้างร่างสินค้า (draft) แล้ว รอคุณตรวจและกดเปิดขาย'),
      'Listing ID: ' + listingId,
      'แก้ไข/เปิดขาย: ' + editUrl,
      'หน้าสินค้า (หลังเปิดขาย): https://www.etsy.com/listing/' + listingId,
      'ราคา: ' + price + ' | จำนวน: ' + quantity + ' | แท็ก: ' + tags.join(', '),
      ...notes,
    ]),
  });
} catch (e) {
  return out({
    etsy_status: 'error',
    etsy_block: block(['❌ ลงขาย Etsy ไม่สำเร็จ: ' + errText(e), ...notes, 'ไฟล์ PDF ยังแนบมาในอีเมลนี้ตามปกติ ลงขายเองได้']),
  });
}
